#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Helpers propres à ce wizard (en dehors de la bibliothèque).

# copier TEXTE : met TEXTE dans le presse-papiers, ou l'affiche à défaut.
copier() {
  if command -v pbcopy >/dev/null 2>&1; then
    printf '%s' "$1" | pbcopy
    printf '  %s✓ copié%s dans le presse-papiers\n' "$GREEN" "$RESET"
  else
    warn "pas de presse-papiers : copie ce bloc à la main"
    printf '%s\n' "$1"
  fi
}

run_wizard() {

TOTAL_STAGES=8

# Toujours depuis la racine du repo, et jamais dans .env.local : la base de prod
# ne doit pas remplacer PGlite pour `pnpm dev`. .env.prod est ignoré par git
# (.env*) et n'est pas chargé par Next.
cd "$(git rev-parse --show-toplevel)"
ENV_FILE=".env.prod"

banner "Simcal : base Neon et déploiement Vercel"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prérequis"
for outil in git pnpm openssl; do
  command -v "$outil" >/dev/null 2>&1 || { warn "$outil est introuvable : installe-le puis relance."; exit 1; }
done
say "Vercel déploie la branche par défaut (main) en production."
git fetch -q origin main || { warn "impossible de récupérer origin/main."; exit 1; }
if ! git show origin/main:package.json 2>/dev/null | grep -q '"next"'; then
  warn "origin/main ne contient pas encore l'app."
  say "Merge simcal-v1 dans main (PR ou merge), pousse, puis relance ce wizard."
  exit 1
fi
note "origin/main contient l'app ($(git log -1 --format='%h %s' origin/main))."
[[ -d node_modules ]] || { say "Installation des dépendances…"; pnpm install; }
pause "Entrée pour continuer"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Neon : créer le projet"
open_url "https://console.neon.tech/app/projects"
step "Clique « New Project »."
step "Nom : simcal. Région : AWS Europe Central 1 (Frankfurt). Postgres : la version proposée."
step "Crée le projet. Sur son tableau de bord, clique « Connect »."
step "Active « Connection pooling » (l'hôte doit contenir « -pooler »)."
step "Affiche le mot de passe puis copie la chaîne complète (postgresql://…)."
while true; do
  ask_secret DATABASE_URL "Colle la chaîne de connexion pooled :"
  if [[ "$DATABASE_URL" != postgres*://* ]]; then
    warn "ça ne ressemble pas à une chaîne postgresql:// ; recommence."; continue
  fi
  # La saisie est masquée : un collage répété passe inaperçu et casse le driver Neon.
  if [[ "${DATABASE_URL#*://}" == *postgres*://* ]]; then
    warn "la chaîne a été collée plusieurs fois ; colle-la une seule fois."; continue
  fi
  note "reçu : ${DATABASE_URL:0:24}… (${#DATABASE_URL} caractères)"
  [[ "$DATABASE_URL" == *-pooler* ]] || warn "l'hôte ne contient pas « -pooler » : vérifie que le pooling est actif."
  break
done
write_env DATABASE_URL "$DATABASE_URL"
pause "Entrée pour continuer"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Neon : migrations et Aliments CIQUAL"
say "On applique les migrations de drizzle/ à la base Neon, puis on importe CIQUAL."
note "Les deux sont répétables : relancer ne duplique rien."
if confirm "Lancer les migrations et l'import CIQUAL sur Neon ?"; then
  DATABASE_URL="$DATABASE_URL" pnpm db:migrate
  DATABASE_URL="$DATABASE_URL" pnpm db:import-ciqual
else
  SKIPPED+=("migrations et CIQUAL : DATABASE_URL=… pnpm db:migrate && DATABASE_URL=… pnpm db:import-ciqual")
  warn "sauté : l'app n'aura pas d'Aliments génériques tant que l'import n'est pas fait."
fi
pause "Entrée pour continuer"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Secrets de l'app"
BETTER_AUTH_SECRET=$(_existing BETTER_AUTH_SECRET || true)
if [[ -z "$BETTER_AUTH_SECRET" ]]; then
  BETTER_AUTH_SECRET=$(openssl rand -base64 32)
  write_env BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET"
else
  note "BETTER_AUTH_SECRET existe déjà dans $ENV_FILE : on le garde (sinon les sessions sautent)."
fi
say "Inscription fermée : seuls ces emails pourront créer un Compte."
while true; do
  ask SIMCAL_ALLOWED_EMAILS "Emails autorisés, séparés par des virgules :"
  [[ "$SIMCAL_ALLOWED_EMAILS" == *@* ]] && break
  warn "il faut au moins un email."
done
write_env SIMCAL_ALLOWED_EMAILS "$SIMCAL_ALLOWED_EMAILS"
pause "Entrée pour continuer"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Vercel : nom du projet"
say "Le nom du projet Vercel donne l'URL publique : https://<nom>.vercel.app."
note "Better Auth a besoin de cette URL. On la vérifiera après le déploiement."
while true; do
  ask VERCEL_PROJET "Nom du projet Vercel (ex. simcal) :"
  [[ "$VERCEL_PROJET" =~ ^[a-z0-9][a-z0-9-]*$ ]] && break
  warn "minuscules, chiffres et tirets seulement."
done
write_env VERCEL_PROJET "$VERCEL_PROJET"
write_env BETTER_AUTH_URL "https://$VERCEL_PROJET.vercel.app"
pause "Entrée pour continuer"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Vercel : importer et déployer"
open_url "https://vercel.com/new"
step "« Import Git Repository » : choisis d-floutier/simcal, puis « Import »."
note "Si le repo n'apparaît pas, autorise-le via « Adjust GitHub App Permissions »."
step "Project Name : $VERCEL_PROJET. Framework Preset : Next.js (détecté)."
step "« Build and Output Settings » : active Override sur Build Command et mets :"
say  "    pnpm db:migrate && pnpm build"
copier "DATABASE_URL=$DATABASE_URL
BETTER_AUTH_SECRET=$BETTER_AUTH_SECRET
BETTER_AUTH_URL=$BETTER_AUTH_URL
SIMCAL_ALLOWED_EMAILS=$SIMCAL_ALLOWED_EMAILS"
step "« Environment Variables » : colle le presse-papiers dans le champ Key."
note "Vercel remplit les 4 lignes (DATABASE_URL, BETTER_AUTH_SECRET, BETTER_AUTH_URL, SIMCAL_ALLOWED_EMAILS)."
step "Clique « Deploy » et attends la fin du build (les migrations passent dedans)."
pause "Entrée une fois le déploiement terminé"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Vercel : réglages après le premier déploiement"
open_url "https://vercel.com/dashboard"
say "Ouvre le projet $VERCEL_PROJET, puis Settings :"
step "Environment Variables → DATABASE_URL → ⋯ → Edit : ne garde que « Production »."
note "Les Previews n'auront pas de base, donc elles ne migreront jamais la prod."
step "Functions → Function Region : Frankfurt (fra1), près de la base Neon."
step "Domains : relève le domaine de production réel."
ask DOMAINE "Domaine de production (Entrée si c'est $VERCEL_PROJET.vercel.app) :"
DOMAINE="${DOMAINE#https://}"; DOMAINE="${DOMAINE%/}"
if [[ -n "$DOMAINE" && "https://$DOMAINE" != "$BETTER_AUTH_URL" ]]; then
  write_env BETTER_AUTH_URL "https://$DOMAINE"
  copier "https://$DOMAINE"
  step "Environment Variables → BETTER_AUTH_URL → Edit : colle la nouvelle valeur."
fi
step "Deployments → le dernier → ⋯ → « Redeploy » pour appliquer région et variables."
pause "Entrée une fois le redéploiement terminé"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Vérifier en production"
open_url "$BETTER_AUTH_URL/inscription"
step "Crée ton Compte avec un email de SIMCAL_ALLOWED_EMAILS."
step "Complète le Profil, puis cherche un Aliment (ex. « pomme ») : les résultats CIQUAL doivent sortir."
note "Si l'inscription échoue, vérifie que BETTER_AUTH_URL correspond exactement au domaine."
pause "Entrée pour terminer"

finish
note "Les valeurs de prod sont dans $ENV_FILE (ignoré par git) : garde-les, ou supprime le fichier."
}

run_wizard "$@"; exit
